"""초6 수학 진단 세트."""
from ._common import make_question,validate_elementary_questions
L,S="초6","수학";K=[4,2,2,2,3,2,4,3,3,2,3,4,2,2,1];T=[50,50,45,45,50,40,50,40,50,55,50,55,45,50,45]
def q(n,a,s,t,o,c,ad=False):return make_question(f"E6MATH-{n:02d}",L,S,a,s,t,o,c,T[n-1],f"계산하면 {o[c-1]}입니다.",f"{s} 과정을 다시 확인할 필요가 있음.",ad)
D=[("수와 연산","분수의 나눗셈","3/4 ÷ 1/8은 얼마인가요?",["3","4","5","6","8"],4),("수와 연산","소수의 나눗셈","7.2 ÷ 3은 얼마인가요?",["1.4","2.4","2.6","3.4","4.2"],2),("도형과 측정","각기둥의 구성","삼각기둥의 면은 모두 몇 개인가요?",["3개","5개","6개","7개","8개"],2),("변화와 관계","비의 간단한 표현","6:9를 가장 간단한 자연수의 비로 나타낸 것은?",["1:2","2:3","3:2","3:4","6:3"],2),("변화와 관계","비율·백분율","15는 60의 몇 %인가요?",["15%","20%","25%","30%","40%"],3),("자료와 가능성","그래프 선택","전체를 하나의 원으로 나타내어 각 부분의 비율을 비교하는 그래프는?",["막대그래프","원그래프","꺾은선그래프","그림그래프","점그래프"],2),("도형과 측정","직육면체의 부피","가로 5 cm, 세로 4 cm, 높이 3 cm인 직육면체의 부피는?",["12 cm³","20 cm³","40 cm³","60 cm³","120 cm³"],4),("도형과 측정","정육면체의 구성","정육면체의 면은 모두 몇 개인가요?",["4개","5개","6개","8개","12개"],3),("변화와 관계","비례식","3:5 = x:20일 때 x는 얼마인가요?",["8","10","12","15","18"],3),("변화와 관계","비례배분","50을 2:3으로 나누었을 때 작은 수는 얼마인가요?",["10","20","25","30","40"],2),("도형과 측정","원의 둘레","원주율을 3.14로 할 때 지름이 10 cm인 원의 둘레는?",["15.7 cm","20 cm","31.4 cm","50 cm","78.5 cm"],3),("도형과 측정","원의 넓이","원주율을 3.14로 할 때 반지름이 4 cm인 원의 넓이는?",["12.56 cm²","25.12 cm²","31.4 cm²","50.24 cm²","62.8 cm²"],4),("도형과 측정","원기둥의 구성","원기둥의 두 밑면에 대한 설명으로 옳은 것은?",["서로 다른 크기의 원이다","서로 합동인 원이다","삼각형이다","직사각형이다","한 개뿐이다"],2),("다음 단계 진입 탐색","소인수분해 개념 진입","12를 소인수의 곱으로 바르게 나타낸 것은?",["2×6","2²×3","3×4","2×3²","12×1"],2,True),("다음 단계 진입 탐색","정수의 크기 비교","-3과 2 중 더 작은 수는?",["-3","-2","0","2","3"],1,True)]
Q=[q(i+1,*x)for i,x in enumerate(D)];validate_elementary_questions(Q,K,625,95)
